    lo, hi = r.get(f"d_{met}_ci95_lo"), r.get(f"d_{met}_ci95_hi")
    if hi is not None and hi < 0: return "**ours**"
    if lo is not None and lo > 0: return "**EPI**"
    return "n.s."
