def include_md(key, title):
    p = pathlib.Path(S[key]["path"])
    if not p.exists(): return f"*{title}: {p} not yet written.*\n"
    t = p.read_text()
    t = re.sub(r"^# .*\n", "", t, count=1)                    # drop the file's own H1
    t = re.sub(r"^(#{2,5}) ", lambda m: "#" * (len(m.group(1)) + 1) + " ", t, flags=re.M)  # demote headings
    return f"## {title}\n\n*Included verbatim from `{p}` (written by its owning agent from its own result files).*\n\n{t}\n"
